// Original Python AST config-selection/start-binding oracle, no business import.
use bson::{Bson, Document};
use quantnight_task_core::{
    lifecycle_policy::task_binding_query,
    start::{priority_config_input, saved_start_config},
};
use serde_json::Value;
fn doc(v: &Value) -> Document {
    Bson::try_from(v.clone())
        .unwrap()
        .as_document()
        .unwrap()
        .clone()
}
#[test]
fn original_python_config_selection_and_start_fences_match() {
    let fixtures: Vec<Value> = serde_json::from_str(GOLDEN).unwrap();
    for (i, c) in fixtures.iter().enumerate() {
        let task = doc(&c["task"]);
        let explicit = c["explicit"].as_str();
        let actual: Result<Bson, String> = match c["op"].as_str().unwrap() {
            "saved" => saved_start_config(&task, explicit).map(Bson::Document),
            "priority" => {
                priority_config_input(&task, explicit).map(|v| v.map_or(Bson::Null, Bson::Document))
            }
            _ => task_binding_query("task", &task, "start").map(Bson::Document),
        };
        if c["expected"].get("error").is_some() {
            assert!(actual.is_err(), "case {i}: {c} actual={actual:?}");
        } else {
            assert_eq!(
                actual,
                Ok(Bson::try_from(c["expected"]["value"].clone()).unwrap()),
                "case {i}: {c}"
            );
        }
    }
}
